sealed interface RefundEvent permits Succeeded, Failed, Pending {}
record Succeeded(String refundId) implements RefundEvent {}
record Failed(String refundId, String failureCode) implements RefundEvent {
    Failed { Objects.requireNonNull(failureCode, "failureCode"); }   // a failure always has a code
}
record Pending(String refundId) implements RefundEvent {}

static RefundEvent parse(String type, String refundId, String failureCode) {
    return switch (type) {
        case "SUCCEEDED" -> new Succeeded(refundId);
        case "FAILED" -> new Failed(refundId, failureCode);
        case "PENDING" -> new Pending(refundId);
        case null, default -> throw new IllegalArgumentException("unknown refund event: " + type);
    };
}

