    data class Failed(val refundId: String, val failureCode: String) : RefundEvent   // non-null: always has a code
    data class Pending(val refundId: String) : RefundEvent
}

fun parse(type: String?, refundId: String, failureCode: String?): RefundEvent = when (type) {
    "SUCCEEDED" -> RefundEvent.Succeeded(refundId)
    "FAILED" -> RefundEvent.Failed(refundId, requireNotNull(failureCode) { "failureCode" })
    "PENDING" -> RefundEvent.Pending(refundId)
    else -> throw IllegalArgumentException("unknown refund event: $type")
